import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_upgrade_map.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_double_dqn.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_dueling_network.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_prioritized_replay.png",d="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_noisy_exploration.png",f=JSON.parse('{"title":"DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里","description":"基础 DQN（深度 Q 网络）通过经验回放和目标网络获得了可训练的闭环，却没有消除所有缺陷。最大化操作会偏爱被高估的动作，单一路径网络难以复用“这个状态整体好不好”的信息，均匀回放把大量计算花在已学会的样本上，ε-greedy（ε-贪心）探索又可能在同一段轨迹里毫无计划地反复抖动。","frontmatter":{"title":"DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里","description":"基础 DQN（深度 Q 网络）通过经验回放和目标网络获得了可训练的闭环，却没有消除所有缺陷。最大化操作会偏爱被高估的动作，单一路径网络难以复用“这个状态整体好不好”的信息，均匀回放把大量计算花在已学会的样本上，ε-greedy（ε-贪心）探索又可能在同一段轨迹里毫无计划地反复抖动。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":15,"source":"2026-08-13/rl_series_12_dqn_advanced.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_12_upgrade_map.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-12-dqn-advanced"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里"}],["meta",{"property":"og:description","content":"基础 DQN（深度 Q 网络）通过经验回放和目标网络获得了可训练的闭环，却没有消除所有缺陷。最大化操作会偏爱被高估的动作，单一路径网络难以复用“这个状态整体好不好”的信息，均匀回放把大量计算花在已学会的样本上，ε-greedy（ε-贪心）探索又可能在同一段轨迹里毫无计划地反复抖动。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-12-dqn-advanced"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_upgrade_map.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里"}],["meta",{"name":"twitter:description","content":"基础 DQN（深度 Q 网络）通过经验回放和目标网络获得了可训练的闭环，却没有消除所有缺陷。最大化操作会偏爱被高估的动作，单一路径网络难以复用“这个状态整体好不好”的信息，均匀回放把大量计算花在已学会的样本上，ε-greedy（ε-贪心）探索又可能在同一段轨迹里毫无计划地反复抖动。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_12_upgrade_map.png"}]],"prev":{"text":"把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环","link":"/rl/rl-series-11-dqn-foundations"},"next":{"text":"不再从 Q 值里挑动作：策略梯度怎样直接学会决策","link":"/rl/rl-series-13-policy-gradient-reinforce"}},"headers":[],"relativePath":"rl/rl-series-12-dqn-advanced.md","filePath":"rl/rl-series-12-dqn-advanced.md","lastUpdated":null}'),s={name:"rl/rl-series-12-dqn-advanced.md"};function p(c,a,u,b,_,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="dqn-仍会高估、浪费样本、探索低效-进阶改造到底改了哪里" tabindex="-1">DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里 <a class="header-anchor" href="#dqn-仍会高估、浪费样本、探索低效-进阶改造到底改了哪里" aria-label="Permalink to &quot;DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里&quot;">​</a></h1><p>基础 DQN（深度 Q 网络）通过经验回放和目标网络获得了可训练的闭环，却没有消除所有缺陷。最大化操作会偏爱被高估的动作，单一路径网络难以复用“这个状态整体好不好”的信息，均匀回放把大量计算花在已学会的样本上，ε-greedy（ε-贪心）探索又可能在同一段轨迹里毫无计划地反复抖动。</p><p>进阶方法并不是给 DQN 随意叠加技巧。Double DQN（双深度 Q 网络）修改目标计算，Dueling DQN（竞争深度 Q 网络）修改网络表示，Prioritized Experience Replay（优先经验回放，PER）修改采样分布，Noisy Network（噪声网络，NoisyNet）修改探索机制。只有把改动位置、解决问题和新增代价一一对应，组合才有可解释性。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-double-dqn-分离选择与评估" tabindex="-1">1.1 Double DQN 分离选择与评估 <a class="header-anchor" href="#_1-1-double-dqn-分离选择与评估" aria-label="Permalink to &quot;1.1 Double DQN 分离选择与评估&quot;">​</a></h3><p>在线网络决定下一状态选哪个动作，目标网络评估该动作的价值。这样可以减少同一组估计误差既负责挑赢家又负责给赢家打高分所造成的最大化偏差。</p><h3 id="_1-2-dueling-dqn-分解状态价值与动作优势" tabindex="-1">1.2 Dueling DQN 分解状态价值与动作优势 <a class="header-anchor" href="#_1-2-dueling-dqn-分解状态价值与动作优势" aria-label="Permalink to &quot;1.2 Dueling DQN 分解状态价值与动作优势&quot;">​</a></h3><p>网络分别学习 Value（状态价值）和 Advantage（动作优势），再聚合为 Q 值。当许多动作效果接近时，状态价值分支可以从更多动作样本共享学习信号。</p><h3 id="_1-3-per-用-学习价值-改变抽样概率" tabindex="-1">1.3 PER 用“学习价值”改变抽样概率 <a class="header-anchor" href="#_1-3-per-用-学习价值-改变抽样概率" aria-label="Permalink to &quot;1.3 PER 用“学习价值”改变抽样概率&quot;">​</a></h3><p>绝对 TD 误差较大的转移通常被更频繁抽取，同时使用 Importance Sampling（重要性采样）权重减轻非均匀采样偏差。高误差不一定代表高价值，也可能来自噪声、异常或错误目标。</p><h3 id="_1-4-noisynet-把探索噪声放进参数" tabindex="-1">1.4 NoisyNet 把探索噪声放进参数 <a class="header-anchor" href="#_1-4-noisynet-把探索噪声放进参数" aria-label="Permalink to &quot;1.4 NoisyNet 把探索噪声放进参数&quot;">​</a></h3><p>可学习的参数噪声使策略在一段状态区域内产生较一致的行为变化。它不同于每一步独立随机动作，也不是向传感器观测或车辆执行器直接加噪声。</p><p><img src="'+o+'" alt="DQN 进阶改造分别作用于目标、表示、采样和探索"></p><h2 id="二、基础-dqn-的问题地图" tabindex="-1">二、基础 DQN 的问题地图 <a class="header-anchor" href="#二、基础-dqn-的问题地图" aria-label="Permalink to &quot;二、基础 DQN 的问题地图&quot;">​</a></h2><h3 id="_2-1-目标计算存在最大化偏差" tabindex="-1">2.1 目标计算存在最大化偏差 <a class="header-anchor" href="#_2-1-目标计算存在最大化偏差" aria-label="Permalink to &quot;2.1 目标计算存在最大化偏差&quot;">​</a></h3><p>普通目标使用 (\\max_a Q(S_{t+1},a;\\theta^-))。当动作估计含噪声时，最大值倾向选择正向误差，目标可能系统性偏高。</p><h3 id="_2-2-网络表示没有显式共享状态价值" tabindex="-1">2.2 网络表示没有显式共享状态价值 <a class="header-anchor" href="#_2-2-网络表示没有显式共享状态价值" aria-label="Permalink to &quot;2.2 网络表示没有显式共享状态价值&quot;">​</a></h3><p>基础网络直接输出每个动作的 Q 值。某些状态下所有动作都差不多，网络仍需分别学习这些输出，没有显式利用共同的状态好坏。</p><h3 id="_2-3-均匀回放忽略样本学习进度" tabindex="-1">2.3 均匀回放忽略样本学习进度 <a class="header-anchor" href="#_2-3-均匀回放忽略样本学习进度" aria-label="Permalink to &quot;2.3 均匀回放忽略样本学习进度&quot;">​</a></h3><p>缓冲区里大量 TD 误差已很小的转移，可能仍与关键失败样本获得相同抽样概率。计算预算没有根据当前学习需要分配。</p><h3 id="_2-4-ε-贪心探索缺乏时间一致性" tabindex="-1">2.4 ε-贪心探索缺乏时间一致性 <a class="header-anchor" href="#_2-4-ε-贪心探索缺乏时间一致性" aria-label="Permalink to &quot;2.4 ε-贪心探索缺乏时间一致性&quot;">​</a></h3><p>每一步独立随机动作可能刚向左探索，下一步又随机向右。长时序任务需要持续尝试一种行为模式时，这种无记忆探索效率较低。</p><h2 id="三、q-值为什么会被高估" tabindex="-1">三、Q 值为什么会被高估 <a class="header-anchor" href="#三、q-值为什么会被高估" aria-label="Permalink to &quot;三、Q 值为什么会被高估&quot;">​</a></h2><h3 id="_3-1-估计误差本身可以有正有负" tabindex="-1">3.1 估计误差本身可以有正有负 <a class="header-anchor" href="#_3-1-估计误差本身可以有正有负" aria-label="Permalink to &quot;3.1 估计误差本身可以有正有负&quot;">​</a></h3><p>假设多个动作真实价值相近，网络对它们的估计分别带有小误差。单看每个动作，误差平均可能接近零。</p><h3 id="_3-2-最大值只关心最乐观的误差" tabindex="-1">3.2 最大值只关心最乐观的误差 <a class="header-anchor" href="#_3-2-最大值只关心最乐观的误差" aria-label="Permalink to &quot;3.2 最大值只关心最乐观的误差&quot;">​</a></h3><p>目标不会随机选择一个动作，而是选择估计最大的动作。即使真正最优动作没有被高估，另一个动作也可能因为噪声成为最大值。</p><h3 id="_3-3-高估会通过自举继续传播" tabindex="-1">3.3 高估会通过自举继续传播 <a class="header-anchor" href="#_3-3-高估会通过自举继续传播" aria-label="Permalink to &quot;3.3 高估会通过自举继续传播&quot;">​</a></h3><p>偏高的下一状态最大值进入当前目标，当前 Q 值被向上推动，随后又成为更早状态的目标组成部分。错误可能沿 Bellman Backup（贝尔曼备份）向前传播。</p><h3 id="_3-4-高-q-值不等于高真实回报" tabindex="-1">3.4 高 Q 值不等于高真实回报 <a class="header-anchor" href="#_3-4-高-q-值不等于高真实回报" aria-label="Permalink to &quot;3.4 高 Q 值不等于高真实回报&quot;">​</a></h3><p>网络预测持续上升，而实际评估回报没有提高，是典型警报。必须同时记录估计 Q 值与真实折扣回报，不能用模型对自己的评分证明策略更好。</p><h2 id="四、double-dqn-怎样拆开两项职责" tabindex="-1">四、Double DQN 怎样拆开两项职责 <a class="header-anchor" href="#四、double-dqn-怎样拆开两项职责" aria-label="Permalink to &quot;四、Double DQN 怎样拆开两项职责&quot;">​</a></h2><h3 id="_4-1-在线网络负责选择动作" tabindex="-1">4.1 在线网络负责选择动作 <a class="header-anchor" href="#_4-1-在线网络负责选择动作" aria-label="Permalink to &quot;4.1 在线网络负责选择动作&quot;">​</a></h3><p>先用当前在线参数选择下一状态最优动作：</p><p>$$ a^*=\\arg\\max_a Q(S_{t+1},a;\\theta) $$</p><h3 id="_4-2-目标网络负责评价动作" tabindex="-1">4.2 目标网络负责评价动作 <a class="header-anchor" href="#_4-2-目标网络负责评价动作" aria-label="Permalink to &quot;4.2 目标网络负责评价动作&quot;">​</a></h3><p>再用目标网络给已选动作估值：</p><p>$$ Y_t^{\\mathrm{Double}}=R_{t+1}+\\gamma Q(S_{t+1},a^*;\\theta^-) $$</p><p>自然终止时仍然去掉自举项。</p><h3 id="_4-3-两个网络已有现成分工" tabindex="-1">4.3 两个网络已有现成分工 <a class="header-anchor" href="#_4-3-两个网络已有现成分工" aria-label="Permalink to &quot;4.3 两个网络已有现成分工&quot;">​</a></h3><p>Double DQN 通常复用基础 DQN 的在线网络和目标网络，不需要另外训练两套彼此独立的智能体。改变的是目标公式中 <code>argmax</code> 和取值分别使用哪个参数。</p><h3 id="_4-4-解耦只能缓解而非消灭偏差" tabindex="-1">4.4 解耦只能缓解而非消灭偏差 <a class="header-anchor" href="#_4-4-解耦只能缓解而非消灭偏差" aria-label="Permalink to &quot;4.4 解耦只能缓解而非消灭偏差&quot;">​</a></h3><p>在线与目标参数仍然相关，因为目标网络定期从在线网络同步。若两个网络犯相似错误，高估仍可能存在；Double DQN 不是价值无偏估计器的保证。</p><p><img src="'+l+'" alt="Double DQN 用在线网络选动作、目标网络评估价值"></p><h2 id="五、怎样验证-double-dqn-是否真的有效" tabindex="-1">五、怎样验证 Double DQN 是否真的有效 <a class="header-anchor" href="#五、怎样验证-double-dqn-是否真的有效" aria-label="Permalink to &quot;五、怎样验证 Double DQN 是否真的有效&quot;">​</a></h2><h3 id="_5-1-同时估计预测值和实际回报" tabindex="-1">5.1 同时估计预测值和实际回报 <a class="header-anchor" href="#_5-1-同时估计预测值和实际回报" aria-label="Permalink to &quot;5.1 同时估计预测值和实际回报&quot;">​</a></h3><p>固定一组评估状态，记录网络最大 Q 值；再从这些状态执行当前策略，多次采样实际折扣回报。两者差距比单看训练曲线更能反映高估。</p><h3 id="_5-2-保持其他配置一致" tabindex="-1">5.2 保持其他配置一致 <a class="header-anchor" href="#_5-2-保持其他配置一致" aria-label="Permalink to &quot;5.2 保持其他配置一致&quot;">​</a></h3><p>基础 DQN 与 Double DQN 对比时，网络、回放、随机种子、训练预算和评估协议应一致，只替换目标计算。</p><h3 id="_5-3-不要只寻找-q-值更低" tabindex="-1">5.3 不要只寻找“Q 值更低” <a class="header-anchor" href="#_5-3-不要只寻找-q-值更低" aria-label="Permalink to &quot;5.3 不要只寻找“Q 值更低”&quot;">​</a></h3><p>价值降低并不自动代表估计更准确。目标是缩小预测与实现回报之间的差距，并改善或保持策略表现，而不是把所有 Q 值压低。</p><h2 id="六、dueling-dqn-为什么分成两条支路" tabindex="-1">六、Dueling DQN 为什么分成两条支路 <a class="header-anchor" href="#六、dueling-dqn-为什么分成两条支路" aria-label="Permalink to &quot;六、Dueling DQN 为什么分成两条支路&quot;">​</a></h2><h3 id="_6-1-状态价值回答-这里整体如何" tabindex="-1">6.1 状态价值回答“这里整体如何” <a class="header-anchor" href="#_6-1-状态价值回答-这里整体如何" aria-label="Permalink to &quot;6.1 状态价值回答“这里整体如何”&quot;">​</a></h3><p>(V(s)) 描述处于状态后整体预期回报，不针对某个具体动作。接近碰撞的状态可能对所有动作都较差，畅通道路可能整体较好。</p><h3 id="_6-2-动作优势回答-这个动作相对如何" tabindex="-1">6.2 动作优势回答“这个动作相对如何” <a class="header-anchor" href="#_6-2-动作优势回答-这个动作相对如何" aria-label="Permalink to &quot;6.2 动作优势回答“这个动作相对如何”&quot;">​</a></h3><p>(A(s,a)) 描述动作相对于状态基线的优势。它把“状态本身危险”与“某个动作比其他动作更合适”分开表示。</p><h3 id="_6-3-共享特征后再分支" tabindex="-1">6.3 共享特征后再分支 <a class="header-anchor" href="#_6-3-共享特征后再分支" aria-label="Permalink to &quot;6.3 共享特征后再分支&quot;">​</a></h3><p>网络通常先提取共同状态特征，再进入一个标量价值分支和一个动作向量优势分支，最后聚合为每个动作的 Q 值。</p><h2 id="七、为什么不能直接计算-v-加-a" tabindex="-1">七、为什么不能直接计算 V 加 A <a class="header-anchor" href="#七、为什么不能直接计算-v-加-a" aria-label="Permalink to &quot;七、为什么不能直接计算 V 加 A&quot;">​</a></h2><h3 id="_7-1-分解存在不可辨识性" tabindex="-1">7.1 分解存在不可辨识性 <a class="header-anchor" href="#_7-1-分解存在不可辨识性" aria-label="Permalink to &quot;7.1 分解存在不可辨识性&quot;">​</a></h3><p>如果给 (V(s)) 加常数 (c)，同时从所有 (A(s,a)) 减去 (c)，Q 值完全不变。没有约束时，两条分支没有唯一含义。</p><h3 id="_7-2-均值归零是常见聚合方式" tabindex="-1">7.2 均值归零是常见聚合方式 <a class="header-anchor" href="#_7-2-均值归零是常见聚合方式" aria-label="Permalink to &quot;7.2 均值归零是常见聚合方式&quot;">​</a></h3><p>常用公式为：</p><p>$$ Q(s,a)=V(s)+A(s,a)-\\frac{1}{|\\mathcal A|}\\sum_{a&#39;}A(s,a&#39;) $$</p><p>优势均值被固定为零后，状态价值等于各动作 Q 值的均值，分解更稳定。</p><h3 id="_7-3-减去最大优势也是一种变体" tabindex="-1">7.3 减去最大优势也是一种变体 <a class="header-anchor" href="#_7-3-减去最大优势也是一种变体" aria-label="Permalink to &quot;7.3 减去最大优势也是一种变体&quot;">​</a></h3><p>原论文讨论了不同聚合形式。实现和实验必须写清所用公式，因为它会改变梯度如何在价值与优势分支间流动。</p><p><img src="'+h+'" alt="Dueling DQN 将共享特征分解为状态价值与动作优势"></p><h2 id="八、dueling-dqn-在什么场景更有帮助" tabindex="-1">八、Dueling DQN 在什么场景更有帮助 <a class="header-anchor" href="#八、dueling-dqn-在什么场景更有帮助" aria-label="Permalink to &quot;八、Dueling DQN 在什么场景更有帮助&quot;">​</a></h2><h3 id="_8-1-许多动作价值相近时更容易共享" tabindex="-1">8.1 许多动作价值相近时更容易共享 <a class="header-anchor" href="#_8-1-许多动作价值相近时更容易共享" aria-label="Permalink to &quot;8.1 许多动作价值相近时更容易共享&quot;">​</a></h3><p>车辆在长直道中央时，多个轻微转向动作短期结果可能接近。状态价值分支可以用不同动作样本共同学习“当前状态整体较好”。</p><h3 id="_8-2-动作差异明显时收益未必大" tabindex="-1">8.2 动作差异明显时收益未必大 <a class="header-anchor" href="#_8-2-动作差异明显时收益未必大" aria-label="Permalink to &quot;8.2 动作差异明显时收益未必大&quot;">​</a></h3><p>若每个状态只有一个动作可避免立即失败，优势分支仍需准确区分动作，状态价值共享不能替代关键动作数据。</p><h3 id="_8-3-架构改造不会修复错误目标" tabindex="-1">8.3 架构改造不会修复错误目标 <a class="header-anchor" href="#_8-3-架构改造不会修复错误目标" aria-label="Permalink to &quot;8.3 架构改造不会修复错误目标&quot;">​</a></h3><p>终止掩码、奖励尺度或回放数据错误时，Dueling DQN 只会用更复杂结构拟合错误。它解决表示效率，不解决所有训练问题。</p><h2 id="九、均匀回放为什么会浪费计算" tabindex="-1">九、均匀回放为什么会浪费计算 <a class="header-anchor" href="#九、均匀回放为什么会浪费计算" aria-label="Permalink to &quot;九、均匀回放为什么会浪费计算&quot;">​</a></h2><h3 id="_9-1-不同样本的当前误差不同" tabindex="-1">9.1 不同样本的当前误差不同 <a class="header-anchor" href="#_9-1-不同样本的当前误差不同" aria-label="Permalink to &quot;9.1 不同样本的当前误差不同&quot;">​</a></h3><p>某些转移已被网络预测得很准，另一些包含意外奖励或新场景，TD 误差较大。均匀抽样不区分两者。</p><h3 id="_9-2-罕见关键转移可能长期抽不到" tabindex="-1">9.2 罕见关键转移可能长期抽不到 <a class="header-anchor" href="#_9-2-罕见关键转移可能长期抽不到" aria-label="Permalink to &quot;9.2 罕见关键转移可能长期抽不到&quot;">​</a></h3><p>缓冲区里若只有少量失败前兆，它们的总抽样概率很低。等待均匀采样重新看到这些数据，可能消耗大量梯度步。</p><h3 id="_9-3-高误差是一种启发而非真理" tabindex="-1">9.3 高误差是一种启发而非真理 <a class="header-anchor" href="#_9-3-高误差是一种启发而非真理" aria-label="Permalink to &quot;9.3 高误差是一种启发而非真理&quot;">​</a></h3><p>TD 误差大可能意味着样本有学习价值，也可能来自随机奖励、部分可观测、标签错误或分布外异常。优先级不能被解释为因果重要性或安全严重度。</p><h2 id="十、per-怎样定义抽样概率" tabindex="-1">十、PER 怎样定义抽样概率 <a class="header-anchor" href="#十、per-怎样定义抽样概率" aria-label="Permalink to &quot;十、PER 怎样定义抽样概率&quot;">​</a></h2><h3 id="_10-1-用-td-误差构造优先级" tabindex="-1">10.1 用 TD 误差构造优先级 <a class="header-anchor" href="#_10-1-用-td-误差构造优先级" aria-label="Permalink to &quot;10.1 用 TD 误差构造优先级&quot;">​</a></h3><p>常见比例式优先级为：</p><p>$$ p_i=(|\\delta_i|+\\varepsilon_{\\mathrm{per}})^\\alpha $$</p><p>小常数保证所有样本仍有机会被抽取，(\\alpha=0) 时退化为均匀回放。</p><h3 id="_10-2-优先级归一化为概率" tabindex="-1">10.2 优先级归一化为概率 <a class="header-anchor" href="#_10-2-优先级归一化为概率" aria-label="Permalink to &quot;10.2 优先级归一化为概率&quot;">​</a></h3><p>$$ P(i)=\\frac{p_i}{\\sum_k p_k} $$</p><p>抽样分布会随网络学习和 TD 误差变化，不再等于缓冲区的经验分布。</p><h3 id="_10-3-新样本需要初始优先级" tabindex="-1">10.3 新样本需要初始优先级 <a class="header-anchor" href="#_10-3-新样本需要初始优先级" aria-label="Permalink to &quot;10.3 新样本需要初始优先级&quot;">​</a></h3><p>常见做法让新转移以当前最大优先级进入，确保至少被学习一次。若初始值过低，新数据可能在尚未计算误差前长期得不到抽取。</p><h2 id="十一、非均匀采样为什么需要纠偏" tabindex="-1">十一、非均匀采样为什么需要纠偏 <a class="header-anchor" href="#十一、非均匀采样为什么需要纠偏" aria-label="Permalink to &quot;十一、非均匀采样为什么需要纠偏&quot;">​</a></h2><h3 id="_11-1-高频抽样会改变优化目标" tabindex="-1">11.1 高频抽样会改变优化目标 <a class="header-anchor" href="#_11-1-高频抽样会改变优化目标" aria-label="Permalink to &quot;11.1 高频抽样会改变优化目标&quot;">​</a></h3><p>高优先级样本对梯度贡献更频繁，若直接训练，网络优化的是优先分布加权后的目标，而不是原经验分布下的均匀目标。</p><h3 id="_11-2-重要性采样权重减轻偏差" tabindex="-1">11.2 重要性采样权重减轻偏差 <a class="header-anchor" href="#_11-2-重要性采样权重减轻偏差" aria-label="Permalink to &quot;11.2 重要性采样权重减轻偏差&quot;">​</a></h3><p>常见权重为：</p><p>$$ w_i=\\left(NP(i)\\right)^{-\\beta} $$</p><p>实际使用时常除以批次或缓冲区内最大权重完成归一化，避免梯度尺度突然放大。</p><h3 id="_11-3-β-通常随训练逐渐增加" tabindex="-1">11.3 β 通常随训练逐渐增加 <a class="header-anchor" href="#_11-3-β-通常随训练逐渐增加" aria-label="Permalink to &quot;11.3 β 通常随训练逐渐增加&quot;">​</a></h3><p>训练早期可以允许更多偏差换取快速学习，后期让 (\\beta) 接近一以加强修正。调度方式属于实验配置，不能省略不报。</p><h3 id="_11-4-每次学习后要更新优先级" tabindex="-1">11.4 每次学习后要更新优先级 <a class="header-anchor" href="#_11-4-每次学习后要更新优先级" aria-label="Permalink to &quot;11.4 每次学习后要更新优先级&quot;">​</a></h3><p>样本被训练后 TD 误差会改变，旧优先级可能已经陈旧。实现需要用新的绝对误差回写对应索引，并处理环形缓冲区覆盖后的索引一致性。</p><p><img src="'+n+'" alt="PER 依据 TD 误差采样，并用重要性权重修正偏差"></p><h2 id="十二、per-会引入哪些新风险" tabindex="-1">十二、PER 会引入哪些新风险 <a class="header-anchor" href="#十二、per-会引入哪些新风险" aria-label="Permalink to &quot;十二、PER 会引入哪些新风险&quot;">​</a></h2><h3 id="_12-1-噪声样本可能被反复放大" tabindex="-1">12.1 噪声样本可能被反复放大 <a class="header-anchor" href="#_12-1-噪声样本可能被反复放大" aria-label="Permalink to &quot;12.1 噪声样本可能被反复放大&quot;">​</a></h3><p>不可预测的随机转移长期保持高误差，会持续占用训练预算。需要观察样本被抽取次数、终止类型和场景标签，而不是只看优先级数值。</p><h3 id="_12-2-低误差不代表没有价值" tabindex="-1">12.2 低误差不代表没有价值 <a class="header-anchor" href="#_12-2-低误差不代表没有价值" aria-label="Permalink to &quot;12.2 低误差不代表没有价值&quot;">​</a></h3><p>简单样本维持价值函数基线和覆盖范围。若优先级过于尖锐，模型可能忘记常见状态，或只围绕异常样本优化。</p><h3 id="_12-3-数据结构实现更复杂" tabindex="-1">12.3 数据结构实现更复杂 <a class="header-anchor" href="#_12-3-数据结构实现更复杂" aria-label="Permalink to &quot;12.3 数据结构实现更复杂&quot;">​</a></h3><p>高效按优先级采样常用 Sum Tree（求和树）或 Segment Tree（线段树）。索引错位、覆盖后优先级未重置、权重广播错误都可能造成隐蔽偏差。</p><h2 id="十三、noisynet-怎样改变探索" tabindex="-1">十三、NoisyNet 怎样改变探索 <a class="header-anchor" href="#十三、noisynet-怎样改变探索" aria-label="Permalink to &quot;十三、NoisyNet 怎样改变探索&quot;">​</a></h2><h3 id="_13-1-在线层参数包含可学习噪声" tabindex="-1">13.1 在线层参数包含可学习噪声 <a class="header-anchor" href="#_13-1-在线层参数包含可学习噪声" aria-label="Permalink to &quot;13.1 在线层参数包含可学习噪声&quot;">​</a></h3><p>权重可以表示为确定部分加噪声部分，例如：</p><p>$$ \\mathbf W=\\boldsymbol\\mu_{\\mathbf W}+\\boldsymbol\\sigma_{\\mathbf W}\\odot\\boldsymbol\\varepsilon_{\\mathbf W} $$</p><p>(\\boldsymbol\\mu) 和 (\\boldsymbol\\sigma) 都通过梯度学习，(\\boldsymbol\\varepsilon) 按实现规则重新采样。</p><h3 id="_13-2-一次参数扰动会影响一组状态" tabindex="-1">13.2 一次参数扰动会影响一组状态 <a class="header-anchor" href="#_13-2-一次参数扰动会影响一组状态" aria-label="Permalink to &quot;13.2 一次参数扰动会影响一组状态&quot;">​</a></h3><p>同一组噪声参数在一段决策中产生一致偏好，使智能体可能持续尝试某种行为模式，而不是每一步独立随机跳转。</p><h3 id="_13-3-探索强度可以由任务学习" tabindex="-1">13.3 探索强度可以由任务学习 <a class="header-anchor" href="#_13-3-探索强度可以由任务学习" aria-label="Permalink to &quot;13.3 探索强度可以由任务学习&quot;">​</a></h3><p>网络能调整 (\\boldsymbol\\sigma) 大小，让不同层和不同特征拥有不同噪声规模。它减少手工 ε 衰减计划的依赖，但仍需要报告噪声采样时机和评估处理。</p><h2 id="十四、noisynet-不是什么" tabindex="-1">十四、NoisyNet 不是什么 <a class="header-anchor" href="#十四、noisynet-不是什么" aria-label="Permalink to &quot;十四、NoisyNet 不是什么&quot;">​</a></h2><h3 id="_14-1-不是给传感器直接加噪声" tabindex="-1">14.1 不是给传感器直接加噪声 <a class="header-anchor" href="#_14-1-不是给传感器直接加噪声" aria-label="Permalink to &quot;14.1 不是给传感器直接加噪声&quot;">​</a></h3><p>观测噪声测试感知鲁棒性，参数噪声用于策略探索，两者目标不同。向摄像头或定位输入任意扰动可能破坏状态语义。</p><h3 id="_14-2-不是给车辆执行器随意抖动" tabindex="-1">14.2 不是给车辆执行器随意抖动 <a class="header-anchor" href="#_14-2-不是给车辆执行器随意抖动" aria-label="Permalink to &quot;14.2 不是给车辆执行器随意抖动&quot;">​</a></h3><p>探索动作仍需经过可行性和安全约束。参数噪声改变价值排序，不授权越过车辆动力学、交通规则或安全屏蔽。</p><h3 id="_14-3-不是完全取消随机性管理" tabindex="-1">14.3 不是完全取消随机性管理 <a class="header-anchor" href="#_14-3-不是完全取消随机性管理" aria-label="Permalink to &quot;14.3 不是完全取消随机性管理&quot;">​</a></h3><p>噪声分布、初始化、采样频率和评估模式都影响结果。关闭 ε-贪心后，仍应检查动作覆盖是否足够。</p><h3 id="_14-4-评估时必须固定协议" tabindex="-1">14.4 评估时必须固定协议 <a class="header-anchor" href="#_14-4-评估时必须固定协议" aria-label="Permalink to &quot;14.4 评估时必须固定协议&quot;">​</a></h3><p>可以关闭噪声或使用固定噪声进行评估，但必须保持所有算法一致。若每次评估都随机重采样，方差中会混入探索因素。</p><p><img src="'+d+'" alt="参数噪声形成跨状态一致的探索偏好"></p><h2 id="十五、这些方法为什么可以组合" tabindex="-1">十五、这些方法为什么可以组合 <a class="header-anchor" href="#十五、这些方法为什么可以组合" aria-label="Permalink to &quot;十五、这些方法为什么可以组合&quot;">​</a></h2><h3 id="_15-1-它们修改的是不同环节" tabindex="-1">15.1 它们修改的是不同环节 <a class="header-anchor" href="#_15-1-它们修改的是不同环节" aria-label="Permalink to &quot;15.1 它们修改的是不同环节&quot;">​</a></h3><p>Double DQN 改目标，Dueling DQN 改表示，PER 改采样，NoisyNet 改行为探索。环节相对正交，因此能够组合在同一个代理中。</p><h3 id="_15-2-正交不等于没有交互" tabindex="-1">15.2 正交不等于没有交互 <a class="header-anchor" href="#_15-2-正交不等于没有交互" aria-label="Permalink to &quot;15.2 正交不等于没有交互&quot;">​</a></h3><p>PER 的优先级来自 TD 误差，而 Double DQN 会改变 TD 目标；NoisyNet 改变行为策略，又会改变进入缓冲区的数据。因此组合后的超参数和分布都可能变化。</p><h3 id="_15-3-rainbow-是系统组合而非魔法配方" tabindex="-1">15.3 Rainbow 是系统组合而非魔法配方 <a class="header-anchor" href="#_15-3-rainbow-是系统组合而非魔法配方" aria-label="Permalink to &quot;15.3 Rainbow 是系统组合而非魔法配方&quot;">​</a></h3><p>Rainbow（彩虹 DQN）把多项改造纳入统一代理，并通过消融研究比较贡献。移植到新任务时仍需逐项验证，不能因为论文组合有效就跳过本地基线。</p><h2 id="十六、怎样设计可信的消融实验" tabindex="-1">十六、怎样设计可信的消融实验 <a class="header-anchor" href="#十六、怎样设计可信的消融实验" aria-label="Permalink to &quot;十六、怎样设计可信的消融实验&quot;">​</a></h2><h3 id="_16-1-从可复现基础-dqn-出发" tabindex="-1">16.1 从可复现基础 DQN 出发 <a class="header-anchor" href="#_16-1-从可复现基础-dqn-出发" aria-label="Permalink to &quot;16.1 从可复现基础 DQN 出发&quot;">​</a></h3><p>先确认基础版本在多个随机种子下能稳定运行。若基线目标、终止语义或评估有错，进阶组合的提升没有可信参照。</p><h3 id="_16-2-每次只改变一个主因素" tabindex="-1">16.2 每次只改变一个主因素 <a class="header-anchor" href="#_16-2-每次只改变一个主因素" aria-label="Permalink to &quot;16.2 每次只改变一个主因素&quot;">​</a></h3><p>分别加入 Double、Dueling、PER 和 NoisyNet，固定训练预算与网络宽度。Dueling 可能增加参数量，需要报告并考虑容量差异。</p><h3 id="_16-3-再测试有依据的组合" tabindex="-1">16.3 再测试有依据的组合 <a class="header-anchor" href="#_16-3-再测试有依据的组合" aria-label="Permalink to &quot;16.3 再测试有依据的组合&quot;">​</a></h3><p>单项结果清楚后，再组合目标、架构和采样改造。记录组合是否产生非加性效果，而不是默认收益可以简单相加。</p><h3 id="_16-4-报告分布而不是单个均值" tabindex="-1">16.4 报告分布而不是单个均值 <a class="header-anchor" href="#_16-4-报告分布而不是单个均值" aria-label="Permalink to &quot;16.4 报告分布而不是单个均值&quot;">​</a></h3><p>对多个种子报告中位数、四分位范围、失败率和样本效率。高方差方法可能平均更高，却有更大概率完全失败。</p><h2 id="十七、自动驾驶应用应守住哪些边界" tabindex="-1">十七、自动驾驶应用应守住哪些边界 <a class="header-anchor" href="#十七、自动驾驶应用应守住哪些边界" aria-label="Permalink to &quot;十七、自动驾驶应用应守住哪些边界&quot;">​</a></h2><h3 id="_17-1-离散高层动作仍需下游验证" tabindex="-1">17.1 离散高层动作仍需下游验证 <a class="header-anchor" href="#_17-1-离散高层动作仍需下游验证" aria-label="Permalink to &quot;17.1 离散高层动作仍需下游验证&quot;">​</a></h3><p>换道、让行或保持车道的 Q 值只表达训练目标下的长期偏好。轨迹规划器仍要检查空间、时间和动力学可行性。</p><h3 id="_17-2-优先回放不能替代安全采样设计" tabindex="-1">17.2 优先回放不能替代安全采样设计 <a class="header-anchor" href="#_17-2-优先回放不能替代安全采样设计" aria-label="Permalink to &quot;17.2 优先回放不能替代安全采样设计&quot;">​</a></h3><p>PER 依据 TD 误差，而不是碰撞严重度。安全关键事件可以拥有独立分层缓冲区或场景采样策略，但这属于额外设计，需要单独纠偏和评估。</p><h3 id="_17-3-探索必须留在受控环境" tabindex="-1">17.3 探索必须留在受控环境 <a class="header-anchor" href="#_17-3-探索必须留在受控环境" aria-label="Permalink to &quot;17.3 探索必须留在受控环境&quot;">​</a></h3><p>NoisyNet 或 ε-贪心应优先用于仿真、封闭场地或经过强约束的可行域。公开道路不能把未知策略探索当成常规在线学习步骤。</p><h3 id="_17-4-高回报不能替代安全论证" tabindex="-1">17.4 高回报不能替代安全论证 <a class="header-anchor" href="#_17-4-高回报不能替代安全论证" aria-label="Permalink to &quot;17.4 高回报不能替代安全论证&quot;">​</a></h3><p>应独立报告碰撞、越界、最小 Time to Collision（碰撞时间）、规则违例、舒适性和安全层介入率。强化学习策略与安全层的贡献也必须分开。</p><h2 id="十八、最常见的实现错误" tabindex="-1">十八、最常见的实现错误 <a class="header-anchor" href="#十八、最常见的实现错误" aria-label="Permalink to &quot;十八、最常见的实现错误&quot;">​</a></h2><h3 id="_18-1-double-dqn-仍用目标网络做-argmax" tabindex="-1">18.1 Double DQN 仍用目标网络做 argmax <a class="header-anchor" href="#_18-1-double-dqn-仍用目标网络做-argmax" aria-label="Permalink to &quot;18.1 Double DQN 仍用目标网络做 argmax&quot;">​</a></h3><p>若选择和评估都来自目标网络，公式就退回普通 DQN。在线网络应输出动作索引，目标网络只对该索引取值。</p><h3 id="_18-2-dueling-聚合忘记中心化优势" tabindex="-1">18.2 Dueling 聚合忘记中心化优势 <a class="header-anchor" href="#_18-2-dueling-聚合忘记中心化优势" aria-label="Permalink to &quot;18.2 Dueling 聚合忘记中心化优势&quot;">​</a></h3><p>直接计算 (V+A) 会留下不可辨识自由度。应明确按均值或最大值中心化，并检查张量维度沿动作轴计算。</p><h3 id="_18-3-per-权重没有乘到逐样本损失" tabindex="-1">18.3 PER 权重没有乘到逐样本损失 <a class="header-anchor" href="#_18-3-per-权重没有乘到逐样本损失" aria-label="Permalink to &quot;18.3 PER 权重没有乘到逐样本损失&quot;">​</a></h3><p>先把批次损失求均值再乘平均权重，无法正确修正每条样本贡献。应保留逐样本损失，乘对应 (w_i) 后再聚合。</p><h3 id="_18-4-noisynet-的噪声从不重采样" tabindex="-1">18.4 NoisyNet 的噪声从不重采样 <a class="header-anchor" href="#_18-4-noisynet-的噪声从不重采样" aria-label="Permalink to &quot;18.4 NoisyNet 的噪声从不重采样&quot;">​</a></h3><p>固定噪声会让代理长期保持同一扰动，过于频繁重采样又可能退化为无时间一致性的抖动。采样时机必须与实现和论文设定一致。</p><h2 id="十九、学到什么程度才算真正掌握" tabindex="-1">十九、学到什么程度才算真正掌握 <a class="header-anchor" href="#十九、学到什么程度才算真正掌握" aria-label="Permalink to &quot;十九、学到什么程度才算真正掌握&quot;">​</a></h2><h3 id="_19-1-能把方法放回训练闭环" tabindex="-1">19.1 能把方法放回训练闭环 <a class="header-anchor" href="#_19-1-能把方法放回训练闭环" aria-label="Permalink to &quot;19.1 能把方法放回训练闭环&quot;">​</a></h3><p>应能指出每个方法改变哪条数据流、哪段公式和哪个模块，并说明没有改变的部分。只会背缩写无法排查组合实现。</p><h3 id="_19-2-能说清收益与代价成对出现" tabindex="-1">19.2 能说清收益与代价成对出现 <a class="header-anchor" href="#_19-2-能说清收益与代价成对出现" aria-label="Permalink to &quot;19.2 能说清收益与代价成对出现&quot;">​</a></h3><p>Double 缓解高估但增加目标依赖，Dueling 改善表示但增加结构，PER 提高学习聚焦度但引入偏差和数据结构，NoisyNet 改善探索但增加随机参数管理。</p><h3 id="_19-3-能用消融而不是故事证明改进" tabindex="-1">19.3 能用消融而不是故事证明改进 <a class="header-anchor" href="#_19-3-能用消融而不是故事证明改进" aria-label="Permalink to &quot;19.3 能用消融而不是故事证明改进&quot;">​</a></h3><p>相同预算、多随机种子、独立评估与分项指标构成最低证据。单条漂亮曲线不能证明某个组件有效。</p><h3 id="_19-4-能看见价值方法之外的下一步" tabindex="-1">19.4 能看见价值方法之外的下一步 <a class="header-anchor" href="#_19-4-能看见价值方法之外的下一步" aria-label="Permalink to &quot;19.4 能看见价值方法之外的下一步&quot;">​</a></h3><p>DQN 系列仍围绕可穷举离散动作。下一篇将转向 Policy Gradient（策略梯度），直接参数化动作分布，为连续动作和随机策略建立新的学习路径。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter7/chapter7.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第七章深度 Q 网络进阶技巧</a></p><p><a href="https://ojs.aaai.org/index.php/AAAI/article/view/10295" target="_blank" rel="noreferrer">DeepMind《Deep Reinforcement Learning with Double Q-learning》</a></p><p><a href="https://proceedings.mlr.press/v48/wangf16.html" target="_blank" rel="noreferrer">DeepMind《Dueling Network Architectures for Deep Reinforcement Learning》</a></p><p><a href="https://arxiv.org/abs/1511.05952" target="_blank" rel="noreferrer">DeepMind《Prioritized Experience Replay》</a></p><p><a href="https://research.google/pubs/noisy-networks-for-exploration/" target="_blank" rel="noreferrer">Google DeepMind《Noisy Networks for Exploration》</a></p><p><a href="https://arxiv.org/abs/1710.02298" target="_blank" rel="noreferrer">DeepMind《Rainbow: Combining Improvements in Deep Reinforcement Learning》</a></p>',180)])])}const P=e(s,[["render",p]]);export{f as __pageData,P as default};
